create policy "own proofs upload" on storage.objects for insert to authenticated with check (bucket_id='payment-proofs' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "own proofs read" on storage.objects for select to authenticated using (bucket_id='payment-proofs' and ((storage.foldername(name))[1] = auth.uid()::text or public.has_role(auth.uid(),'admin')));